import{_ as s,o as i,c as t,a2 as a}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Programme fondamental de la Progression Commune des Dix Mille Races","description":"","frontmatter":{},"headers":[],"relativePath":"fr/05-万族共进基本纲领.md","filePath":"fr/05-万族共进基本纲领.md","lastUpdated":1789183869000}'),r={name:"fr/05-万族共进基本纲领.md"};function n(o,e,l,d,c,u){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="programme-fondamental-de-la-progression-commune-des-dix-mille-races" tabindex="-1">Programme fondamental de la Progression Commune des Dix Mille Races <a class="header-anchor" href="#programme-fondamental-de-la-progression-commune-des-dix-mille-races" aria-label="Permalink to &quot;Programme fondamental de la Progression Commune des Dix Mille Races&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>05</td></tr><tr><td>Module</td><td>Principes généraux et paramètres fondamentaux</td></tr><tr><td>Mots-clés</td><td>Dix Mille Races, Progression commune, Égalité raciale, Évolution collaborative, République</td></tr></tbody></table><h2 id="i-definition-et-portee-des-dix-mille-races" tabindex="-1">I. Définition et portée des Dix Mille Races <a class="header-anchor" href="#i-definition-et-portee-des-dix-mille-races" aria-label="Permalink to &quot;I. Définition et portée des Dix Mille Races&quot;">​</a></h2><p>« Les Dix Mille Races » est le terme collectif désignant toutes les formes de vie de l&#39;Univers Originel des Dix Mille Esprits et de l&#39;Ancre Équilibrée possédant le potentiel de perception et d&#39;évolution. « Dix mille » ne signifie pas précisément dix mille races, mais exprime leur nombre immense, englobant toutes les formes de vie connues et inconnues. La portée des Dix Mille Races comprend, sans s&#39;y limiter : la race humaine et diverses races humanoïdes, les vies énergétiques, les entités de conscience, les vies mécaniques, les vies intelligentes de type végétal, les vies anomales, les races hybrides inter-plans, etc.</p><p>La civilisation symbiotique adhère au principe d&#39;« égalité des formes de vie », n&#39;utilisant ni la composition matérielle, ni le niveau d&#39;énergie, ni la complexité de conscience de la vie comme critères de hiérarchisation. Toute race — quel que soit le niveau moyen de ses membres, sa taille de population ou sa longueur historique — jouit d&#39;un statut et de droits égaux au sein de la civilisation symbiotique.</p><h2 id="ii-concepts-centraux-de-la-progression-commune-des-dix-mille-races" tabindex="-1">II. Concepts centraux de la Progression Commune des Dix Mille Races <a class="header-anchor" href="#ii-concepts-centraux-de-la-progression-commune-des-dix-mille-races" aria-label="Permalink to &quot;II. Concepts centraux de la Progression Commune des Dix Mille Races&quot;">​</a></h2><p>La Progression Commune des Dix Mille Races est l&#39;un des objectifs centraux de la Civilisation Symbiotique de l&#39;Ancre, et ses concepts fondamentaux peuvent se résumer en quatre points :</p><ol><li><strong>L&#39;évolution n&#39;est pas un jeu à somme nulle entre les races</strong> : l&#39;évolution d&#39;une race ne se fait pas au prix du sacrifice des autres races ; au contraire, la collaboration entre les races peut produire des effets évolutifs synergiques.</li><li><strong>Chaque race possède des avantages évolutifs uniques</strong> : les différentes races ont formé leurs propres traits et talents au cours d&#39;une longue évolution ; ces traits sont la précieuse richesse de la diversité évolutive cosmique.</li><li><strong>Les races en retard ont le droit de recevoir un soutien</strong> : pour les races de niveau évolutif inférieur, la civilisation symbiotique a l&#39;obligation de fournir un soutien en éducation, ressources, technologie et autres aspects, les aidant à trouver des voies évolutives adaptées.</li><li><strong>Les races avancées ont l&#39;obligation d&#39;assumer des responsabilités</strong> : les races de niveau évolutif supérieur assument davantage de responsabilités publiques dans la civilisation symbiotique, notamment l&#39;entretien des ancres, la transmission des connaissances et la protection civilisationnelle.</li></ol><h2 id="iii-principes-fondamentaux-de-la-progression-commune-des-dix-mille-races" tabindex="-1">III. Principes fondamentaux de la Progression Commune des Dix Mille Races <a class="header-anchor" href="#iii-principes-fondamentaux-de-la-progression-commune-des-dix-mille-races" aria-label="Permalink to &quot;III. Principes fondamentaux de la Progression Commune des Dix Mille Races&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Principe</th><th>Signification</th><th>Exigences spécifiques</th></tr></thead><tbody><tr><td>Principe d&#39;égalité raciale</td><td>Toutes les races sont égales en statut juridique et en droit à l&#39;évolution</td><td>La discrimination raciale est interdite ; les postes publics sont ouverts à toutes les races</td></tr><tr><td>Principe de respect culturel</td><td>Respecter les traditions culturelles et les modes de vie de chaque race</td><td>Pas d&#39;assimilation culturelle forcée ; soutenir la transmission et le développement des cultures raciales</td></tr><tr><td>Principe de complémentarité des avantages</td><td>Encourager les races à exploiter leurs avantages respectifs pour collaborer</td><td>Établir une base de données des talents raciaux ; promouvoir des projets de coopération interraciale</td></tr><tr><td>Principe de soutien aux retardataires</td><td>Fournir un soutien supplémentaire aux races de niveau évolutif inférieur</td><td>Créer des fonds de développement racial ; fournir une éducation ciblée et une allocation de ressources</td></tr><tr><td>Principe d&#39;autonomie et de co-gouvernance</td><td>Les affaires internes des races sont autonomes ; les affaires interraciales sont co-gouvernées</td><td>Chaque race jouit du pouvoir législatif interne ; les affaires publiques sont décidées par les institutions républicaines</td></tr><tr><td>Principe de résolution pacifique des conflits</td><td>Les conflits raciaux sont résolus par des moyens pacifiques</td><td>Les guerres entre races sont interdites ; les conflits sont soumis à l&#39;arbitrage du Tribunal Symbiotique</td></tr></tbody></table><h2 id="iv-voies-de-mise-en-œuvre-de-la-progression-commune-des-dix-mille-races" tabindex="-1">IV. Voies de mise en œuvre de la Progression Commune des Dix Mille Races <a class="header-anchor" href="#iv-voies-de-mise-en-œuvre-de-la-progression-commune-des-dix-mille-races" aria-label="Permalink to &quot;IV. Voies de mise en œuvre de la Progression Commune des Dix Mille Races&quot;">​</a></h2><p>La Progression Commune des Dix Mille Races n&#39;est pas un slogan, mais se réalise progressivement par les voies concrètes suivantes :</p><h3 id="_4-1-education-commune" tabindex="-1">4.1 Éducation commune <a class="header-anchor" href="#_4-1-education-commune" aria-label="Permalink to &quot;4.1 Éducation commune&quot;">​</a></h3><p>Établir un système d&#39;éducation symbiotique interracial, où les jeunes de toutes les races peuvent recevoir gratuitement une éducation évolutive de base. Le contenu éducatif comprend les méthodes fondamentales des Trois Cents Systèmes de Culture de l&#39;Origine, l&#39;éthique anti-prédation, la Charte de la Civilisation Symbiotique et les connaissances cosmiques communes. Parallèlement, les traditions culturelles et éducatives de chaque race sont respectées, permettant une éducation à caractère racial en complément de l&#39;éducation commune.</p><h3 id="_4-2-partage-des-ressources" tabindex="-1">4.2 Partage des ressources <a class="header-anchor" href="#_4-2-partage-des-ressources" aria-label="Permalink to &quot;4.2 Partage des ressources&quot;">​</a></h3><p>Par le Système de Contrat Lié à la Production, les ressources de culture cosmiques sont réparties de manière globale selon la population raciale, les besoins évolutifs et les niveaux de contribution. Pour les races dépourvues de ressources, un ajustement des ressources inter-plans est effectué via le réseau d&#39;ancres. Le monopole des ressources de culture publiques par une race quelconque est interdit.</p><h3 id="_4-3-recherche-technologique-conjointe" tabindex="-1">4.3 Recherche technologique conjointe <a class="header-anchor" href="#_4-3-recherche-technologique-conjointe" aria-label="Permalink to &quot;4.3 Recherche technologique conjointe&quot;">​</a></h3><p>La coopération technologique interraciale est encouragée, en particulier les projets de recherche combinant les capacités innées des différentes races avec l&#39;ingénierie des lois. La civilisation symbiotique a créé un « Fonds de recherche conjointe des Dix Mille Races » pour financer les équipes de recherche interraciales. Les résultats de recherche sont ouverts gratuitement à toutes les races.</p><h3 id="_4-4-mobilite-des-talents" tabindex="-1">4.4 Mobilité des talents <a class="header-anchor" href="#_4-4-mobilite-des-talents" aria-label="Permalink to &quot;4.4 Mobilité des talents&quot;">​</a></h3><p>Briser les barrières de talents entre les races, permettant aux cultivateurs de se déplacer et de communiquer librement entre les zones de peuplement des différentes races. Établir un système de mentorat interracial, où les cultivateurs avancés peuvent guider les cultivateurs juniors d&#39;autres races.</p><h3 id="_4-5-participation-republicaine" tabindex="-1">4.5 Participation républicaine <a class="header-anchor" href="#_4-5-participation-republicaine" aria-label="Permalink to &quot;4.5 Participation républicaine&quot;">​</a></h3><p>L&#39;Assemblée de la République des Dix Mille Races répartit les sièges selon la population et la contribution des races, garantissant aux petites races un canal d&#39;expression. Les décisions de l&#39;Assemblée combinent consensus et vote majoritaire ; les questions touchant aux intérêts fondamentaux d&#39;une race exigent le consentement de la race concernée.</p><h2 id="v-politiques-pour-les-races-speciales" tabindex="-1">V. Politiques pour les races spéciales <a class="header-anchor" href="#v-politiques-pour-les-races-speciales" aria-label="Permalink to &quot;V. Politiques pour les races spéciales&quot;">​</a></h2><p>Pour les races se trouvant dans des circonstances particulières, la civilisation symbiotique adopte des politiques différenciées :</p><ul><li><strong>Races menacées</strong> : établir des plans de protection des races, fournissant un soutien d&#39;urgence en ressources et la protection des habitats, pour aider à restaurer leurs populations</li><li><strong>Races de vies anomales</strong> : les évaluer et les installer selon le processus standardisé de trois catégories pour les vies anomales, garantissant la protection de leur droit à l&#39;évolution</li><li><strong>Races hybrides inter-plans</strong> : reconnaître leur double identité raciale, garantissant leurs droits égaux dans les cultures des deux races</li><li><strong>Anciennes races prédatrices</strong> : pour les races ayant jadis pratiqué le prédationisme, après l&#39;achèvement de la réforme éthique et de la transformation systémique, leur accorder un statut pleinement égal, sans discrimination rétroactive historique</li></ul><h2 id="vi-indicateurs-de-mesure-de-la-progression-commune-des-dix-mille-races" tabindex="-1">VI. Indicateurs de mesure de la Progression Commune des Dix Mille Races <a class="header-anchor" href="#vi-indicateurs-de-mesure-de-la-progression-commune-des-dix-mille-races" aria-label="Permalink to &quot;VI. Indicateurs de mesure de la Progression Commune des Dix Mille Races&quot;">​</a></h2><p>La civilisation symbiotique a établi un « Indice de Progression Commune des Dix Mille Races », mesurant les progrès selon les dimensions suivantes :</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Indicateur</th><th>Objectif</th></tr></thead><tbody><tr><td>Couverture évolutive</td><td>Proportion de races connectées au système de culture</td><td>100%</td></tr><tr><td>Équilibre des niveaux</td><td>Coefficient de différence des niveaux moyens entre races</td><td>En rétrécissement continu</td></tr><tr><td>Densité de collaboration</td><td>Nombre et profondeur des projets de coopération interraciale</td><td>En augmentation continue</td></tr><tr><td>Vitalité culturelle</td><td>Activité de transmission et d&#39;innovation culturelles raciales</td><td>Maintien de la diversité</td></tr><tr><td>Incidence des conflits</td><td>Fréquence des conflits entre races</td><td>En baisse continue</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La Progression Commune des Dix Mille Races est l&#39;un des objectifs ultimes de la Civilisation Symbiotique de l&#39;Ancre et une condition nécessaire à l&#39;ascension dimensionnelle globale de l&#39;univers. Dans le cadre de la civilisation symbiotique, chaque race peut trouver une voie évolutive adaptée, et l&#39;unicité de chaque race peut être respectée et mise en valeur. La Progression Commune des Dix Mille Races ne vise pas à éliminer les différences, mais à réaliser l&#39;harmonie dans la différence et la symbiose dans la diversité.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Déclaration de la Civilisation Symbiotique de l&#39;Ancre)</li><li>50-万族谱系总览 (Vue d&#39;ensemble de la généalogie des Dix Mille Races)</li><li>77-万族共和成立 (Fondation de la République des Dix Mille Races)</li></ul>',32)])])}const h=s(r,[["render",n]]);export{p as __pageData,h as default};
